%%

IZO_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Izana.nc', IZO_st);

names_rd=fieldnames(IZO_rd);
%%
%IZO_rd_MAAP25=read_ebas_merged_STN('C:\github_trend\raw_data\IZO_abs_25.nc', IZO_st);
IZO_rd2=timetable(datetime(datetime(1900,1,1) + days(IZO_abs_25_3.Variables(1).Value)));
IZO_rd2.BaR_Amaap25=IZO_abs_25_3.Variables(2).Value./1.05;
IZO_rd2_d=retime(IZO_rd2,'daily',@nanmedian);
IZO_rd.BaR0_A(IZO_rd.Time>datetime(2024,12,31,23,59,59))=IZO_rd2_d.BaR_Amaap25;
%%
% 2025 scat G and R with false truncation, new data send
IZO_rd3=read_nasa_ames_def('ES0018G.20250101000000.20260101000000.nephelometer.aerosol_scattering_coefficient.pm10.1y.1h.ES07L_TSI_3563_SN70738230-PM10amb.ES07L_sct_coef_PM10amb_TSI3562_v1.lev2.nas','C:/github_trend/raw_data/');
IZO_rd3_d=retime(IZO_rd3,'daily',@nanmedian);
IZO_rd.BsR0_S(IZO_rd.Time>datetime(2024,12,31,23,59,59))=IZO_rd3_d.sc700;
IZO_rd.BsG0_S(IZO_rd.Time>datetime(2024,12,31,23,59,59))=IZO_rd3_d.sc550;
IZO_rd.BbsR0_S(IZO_rd.Time>datetime(2024,12,31,23,59,59))=IZO_rd3_d.bsc700;
